-- Ficha de Puerto Plata (José Manuel Cobles).
--
-- La biografía de relleno lo describía en términos genéricos, sin un solo hecho verificable.
-- first_name: José Manuel (completo). occupations: guitarist, songwriter. instruments:
-- guitar. primary_genre queda en merengue: el estilo real es un cruce de son, bolero y
-- merengue de guitarra que retroactivamente se lee como precursor de la bachata; no hay un
-- valor único claramente mejor en la taxonomía actual, así que no se tocó (ver
-- CONFLICTOS_DE_DATO.md). Juan Lockward, Daniel Rodríguez y Ernesto Sanabria Almonte no
-- tienen ficha: ver MUSICOS_PENDIENTES.md.

UPDATE artists SET first_name = 'José Manuel', occupations = '["guitarist","songwriter"]'::jsonb,
       instruments = ARRAY['guitar']::text[] WHERE slug = 'puerto-plata';

